s='''def transform(grid):
    out=[row[:] for row in grid]
    # Nonzero horizontal runs of length >= 2 are the task's sequence templates.
    templates=[]
    for row in grid:
        c=0
        while c<len(row):
            if row[c]==0:
                c+=1
                continue
            start=c
            while c<len(row) and row[c]!=0:
                c+=1
            if c-start>=2:
                templates.append((row[start:c],start))
    for r,row in enumerate(grid):
        pts=[(c,v) for c,v in enumerate(row) if v]
        if len(pts)!=1:
            continue
        c,v=pts[0]
        candidates=[]
        for seq,source_start in templates:
            for phase,color in enumerate(seq):
                if color==v:
                    # Prefer longer exact template; tie break by first available.
                    candidates.append((len(seq),seq,phase))
        if not candidates:
            continue
        _,seq,phase=max(candidates,key=lambda z:z[0])
        start=c-phase
        for i,color in enumerate(seq):
            if 0<=start+i<len(row):
                out[r][start+i]=color
    return out
'''
